public static int sumQueue(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int sum = 0;
    while (!q.isEmpty()) {
        int x = q.remove();
        sum = sum + x;
        temp.insert(x);
    }
    // מחזירים את האיברים — התור חוזר להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return sum;
}

public static int countEven(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int count = 0;
    while (!q.isEmpty()) {
        int x = q.remove();
        if (x % 2 == 0) {
            count++;
        }
        temp.insert(x);
    }
    // מחזירים את האיברים — התור חוזר להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return count;
}

